def options(state, n):
    """The three GENUINE, LEGAL option lists.  No self-loops by construction."""
    D = len(state)
    rep, rel, exc = [], [], []
    for li in range(D):
        layer = list(state[li])
        for k, old in enumerate(layer):
            rest = layer[:k] + layer[k + 1:]
            fr = KS.free(n, rest)
            for a, b in itertools.combinations(sorted(fr), 2):
                if (a, b) == old:
                    continue                      # identity: excluded, not wasted
                nl = [list(x) for x in state]
                nl[li] = rest + [(a, b)]
                rep.append(KS.canon(nl))
        for lj in range(D):
            if lj == li:
                continue
            fj = set(KS.free(n, state[lj]))
            for c in layer:
                if c[0] in fj and c[1] in fj:
                    nl = [list(x) for x in state]
                    nl[li] = [x for x in layer if x != c]
                    nl[lj] = list(state[lj]) + [c]
                    rel.append(KS.canon(nl))
        for lj in range(li + 1, D):               # unordered: each swap once
            other = list(state[lj])
            if not other:
                continue
            ui, uj = KS.used(layer), KS.used(other)
            for ci in layer:
                for cj in other:
                    if ci == cj:
                        continue
                    if (set(cj) & (ui - set(ci))) or (set(ci) & (uj - set(cj))):
                        continue
                    nl = [list(x) for x in state]
                    nl[li] = [x for x in layer if x != ci] + [cj]
                    nl[lj] = [x for x in other if x != cj] + [ci]
                    exc.append(KS.canon(nl))
    return {"replace": rep, "relocate": rel, "exchange": exc}


def lean_law(state, n):
    """EXACT one-step proposal law.  Returns (moves, selfloops) like the v1_5 tool."""
    op = options(state, n)
    live = [k for k in ("replace", "relocate", "exchange") if op[k]]
    if not live:
        return {}, {"no_legal_move": F(1)}
    Z = sum(W[k] for k in live)
    mv = {}
    for k in live:
        p = W[k] / Z / len(op[k])
        for s in op[k]:
            mv[s] = mv.get(s, F(0)) + p
    return mv, {}


def sample(state, n, rnd):
    """Runtime sampler matching lean_law exactly (uniform inside each option list)."""
    op = options(state, n)
    live = [k for k in ("replace", "relocate", "exchange") if op[k]]
    if not live:
        return state
    tot = sum(float(W[k]) for k in live)
    r = rnd.random() * tot
    acc = 0.0
    for k in live:
        acc += float(W[k])
        if r < acc:
            return rnd.choice(op[k])
    return rnd.choice(op[live[-1]])


