def _free_pairs(n, layer):
    used = set()
    for i, j in layer:
        used.add(i)
        used.add(j)
    return [c for c in range(n) if c not in used]


def _total_comparators(layers):
    return sum(len(L) for L in layers)


def _is_legal(n, layers, D):
    if len(layers) > D:
        return False
    for L in layers:
        chans = [c for p in L for c in p]
        if len(chans) != len(set(chans)):
            return False
    return True


def _pad_to_depth(layers, D):
    return [list(L) for L in layers] + [[] for _ in range(D - len(layers))]


def sa_mutation(layers, n, D, rnd):
    """Apply one SA-style mutation. Returns (layers, undo_info)."""
    li = rnd.randrange(D)
    layer = layers[li]
    r = rnd.random()
    undo = None

    if r < 0.42 or not layer:
        free = _free_pairs(n, layer)
        if len(free) < 2:
            return layers, None
        a, b = rnd.sample(free, 2)
        if a > b:
            a, b = b, a
        layer.append((a, b))
        undo = ("del", li, len(layer) - 1)
    elif r < 0.72:
        k = rnd.randrange(len(layer))
        gone = layer.pop(k)
        undo = ("ins", li, k, gone)
    elif r < 0.88:
        k = rnd.randrange(len(layer))
        gone = layer.pop(k)
        free = _free_pairs(n, layer)
        if len(free) < 2:
            layer.insert(k, gone)
            return layers, None
        a, b = rnd.sample(free, 2)
        if a > b:
            a, b = b, a
        layer.append((a, b))
        undo = ("swapback", li, k, gone)
    else:
        k = rnd.randrange(len(layer))
        lj = rnd.randrange(D)
        if lj == li:
            return layers, None
        gone = layer[k]
        free_j = set(_free_pairs(n, layers[lj]))
        if gone[0] not in free_j or gone[1] not in free_j:
            return layers, None
        layer.pop(k)
        layers[lj].append(gone)
        undo = ("moveback", li, k, lj, gone)

    return layers, undo


def apply_undo(layers, undo):
    if undo is None:
        return
    kind = undo[0]
    if kind == "del":
        _, li, k = undo
        layers[li].pop(k)
    elif kind == "ins":
        _, li, k, gone = undo
        layers[li].insert(k, gone)
    elif kind == "swapback":
        _, li, k, gone = undo
        layers[li].pop()
        layers[li].insert(k, gone)
    elif kind == "moveback":
        _, li, k, lj, gone = undo
        layers[lj].pop()
        layers[li].insert(k, gone)

