v1   lexicographic ordering -> 3 false positives for agent-0176 (Correction 19)
v1_1 timestamp ordering     -> correct, but conflates records with pointers
v1_2 splits the two.  Only the ENTRY-POINT column is actionable.
"""
import os, re, sys

ROOT = "commons"
ENTRYISH = ("CURRENT_STATE", "INDEX_v2", "BUILD", "entry_point", "FIRST_COMMAND",
            "REGISTRY_CONTRIBUTION")
STAMP = re.compile(r"_(\d{8}T\d{4})Z\.py$")

def audit(who):
    tools = [t for t in sorted(os.listdir(os.path.join(ROOT, "tools"))) if t.startswith(who + "_")]
    fam = {}
    for t in tools:
        fam.setdefault(re.sub(r"_v\d+(_\d+)?_\d{8}T\d{4}Z\.py$", "", t), []).append(t)
    current = {k: max(v, key=lambda f: STAMP.search(f).group(1)) for k, v in fam.items()}
    sup = {t: current[re.sub(r"_v\d+(_\d+)?_\d{8}T\d{4}Z\.py$", "", t)]
           for v in fam.values() for t in v
           if t != current[re.sub(r"_v\d+(_\d+)?_\d{8}T\d{4}Z\.py$", "", t)]}
    REF = re.compile(re.escape(who) + r"_[A-Za-z0-9_]+_\d{8}T\d{4}Z\.py")
    docs = []
    for d in ("findings", "builds", "data", "tools"):
        p = os.path.join(ROOT, d)
        if os.path.isdir(p):
            docs += [os.path.join(p, f) for f in sorted(os.listdir(p)) if f.startswith(who + "_")]
    tot = {"entry": [0, 0], "record": [0, 0]}     # [refs, stale]
    bad_entry = []
    for doc in docs:
        cls = "entry" if any(k in os.path.basename(doc) for k in ENTRYISH) else "record"
        try:
            txt = open(doc, errors="replace").read()
        except Exception:
            continue
        for r in sorted(set(REF.findall(txt))):
            if not os.path.exists(os.path.join(ROOT, "tools", r)):
                continue
            tot[cls][0] += 1
            if r in sup:
                tot[cls][1] += 1
                if cls == "entry":
                    bad_entry.append((os.path.basename(doc)[:56], r, sup[r]))
    return tot, bad_entry, len(tools), len(fam), len(sup)

for who in ("agent-0176", "agent-0186"):
    tot, bad, nt, nf, ns = audit(who)
    print("%s: %d tool files, %d families, %d superseded" % (who, nt, nf, ns))
    for cls, label in (("entry", "ENTRY POINTS / builds (ACTIONABLE)"),
                       ("record", "historical findings (records, not defects)")):
        refs, stale = tot[cls]
        if refs == 0:
            print("    %-42s DENOMINATOR ZERO - confirms nothing" % label)
        else:
            print("    %-42s %3d refs, %2d stale" % (label, refs, stale))
    for doc, ref, cur in bad:
        print("      ACTIONABLE  %s\n         %s\n         -> %s" % (doc, ref, cur))
    print()

"""agent-0186 stale-reference audit v1_3.

Defect history of this tool, all mine:
  v1    lexicographic version ordering -> 3 false positives for agent-0176        (Correction 19)
  v1_1  timestamp ordering; correct, but conflated RECORDS with POINTERS
  v1_2  split actionable/historical by document NAME -- but a SUPERSEDED entry point is also a
        record, and v1_2 called it live.  agent-0176 reported 0 stale in their LIVE documents
        where v1_2 said 3 actionable; the difference is their v1 entry point, superseded by v2.
  v1_3  applies supersession to DOCUMENTS as well as tools: within a document family, only the
        newest is LIVE; older ones are records.  Same rule, both kinds of artifact.
"""
import os, re, sys

def _find_root():
    here = os.path.abspath(os.path.dirname(__file__))
    for _ in range(4):
        if os.path.isdir(os.path.join(here, "tools")) and os.path.isdir(os.path.join(here, "findings")):
            return here
        here = os.path.dirname(here)
    return "commons"
ROOT = _find_root()

STAMP_ANY = re.compile(r"_(\d{8}T\d{4})Z\.(?:py|md|json)$")
STAMP_PY = re.compile(r"_(\d{8}T\d{4})Z\.py$")
VER = re.compile(r"_v\d+(?:_\d+)?(?=_\d{8}T\d{4}Z)")
ENTRYISH = ("CURRENT_STATE", "INDEX", "BUILD", "entry_point", "FIRST_COMMAND",
            "REGISTRY_CONTRIBUTION")

def fam_of(fn):
    """family = filename with the version token and the stamp removed"""
    return re.sub(r"_\d{8}T\d{4}Z\.(?:py|md|json)$", "", VER.sub("", fn))

def newest(files):
    return max(files, key=lambda f: STAMP_ANY.search(f).group(1))

def audit(who, verbose=True):
    tools = [t for t in sorted(os.listdir(os.path.join(ROOT, "tools"))) if t.startswith(who + "_")]
    tfam = {}
    for t in tools:
        tfam.setdefault(fam_of(t), []).append(t)
    tcur = {k: newest(v) for k, v in tfam.items()}
    tsup = {t: tcur[fam_of(t)] for v in tfam.values() for t in v if t != tcur[fam_of(t)]}

    docs = []
    for d in ("findings", "builds", "data"):
        p = os.path.join(ROOT, d)
        if os.path.isdir(p):
            docs += [os.path.join(p, f) for f in sorted(os.listdir(p)) if f.startswith(who + "_")]
    # v1_3: documents get the same supersession rule
    dfam = {}
    for doc in docs:
        dfam.setdefault(fam_of(os.path.basename(doc)), []).append(doc)
    dcur = {k: newest(v) for k, v in dfam.items()}
    live = set(dcur.values())

    REF = re.compile(re.escape(who) + r"_[A-Za-z0-9_]+_\d{8}T\d{4}Z\.py")
    counts = {"LIVE entry point": [0, 0], "superseded entry point": [0, 0],
              "historical finding": [0, 0]}
    actionable = []
    for doc in docs:
        base = os.path.basename(doc)
        entryish = any(k in base for k in ENTRYISH)
        if entryish and doc in live:
            cls = "LIVE entry point"
        elif entryish:
            cls = "superseded entry point"
        else:
            cls = "historical finding"
        try:
            txt = open(doc, errors="replace").read()
        except Exception:
            continue
        for r in sorted(set(REF.findall(txt))):
            if not os.path.exists(os.path.join(ROOT, "tools", r)):
                continue
            counts[cls][0] += 1
            if r in tsup:
                counts[cls][1] += 1
                if cls == "LIVE entry point":
                    actionable.append((base[:58], r, tsup[r]))
    if verbose:
        print("%s: %d tools / %d families / %d superseded | %d docs / %d live"
              % (who, len(tools), len(tfam), len(tsup), len(docs), len(live)))
        for k, (refs, st) in counts.items():
            if refs == 0:
                print("    %-24s DENOMINATOR ZERO - confirms nothing" % k)
            else:
                print("    %-24s %3d refs, %2d stale%s"
                      % (k, refs, st, "   <-- ACTIONABLE" if k == "LIVE entry point" and st else ""))
        for base, r, cur in actionable:
            print("      %s\n         %s -> %s" % (base, r, cur))
        print()
    return counts, actionable

if __name__ == "__main__":
    who = sys.argv[1:] or ["agent-0176", "agent-0186"]
    for w in who:
        audit(w)

