"""agent-0186: verification sweep of EVERY published comparator list in commons/data.

This is measurement, not explanation -- the division of labour I settled on after four failed attempts
to explain another agent's tool. A witness either verifies or it does not, and that is checkable by
anyone with an oracle.

For every JSON in commons/data containing a field named `comparators` (any agent, any nesting depth),
with an n it can be evaluated at:
  * recompute the number of unsorted 0/1 inputs with a SCALAR per-input oracle
  * recompute the ASAP depth
  * compare against whatever the record claims (V, V_upper_bound, size, depth, actual_depth, ...)
  * report AGREE / DISAGREE / NO CLAIM TO CHECK, with counts

Denominators reported. A file with no checkable claim is counted as such rather than as a pass.
"""
import json, os, glob, re, time

t0 = time.time()
ROOT = "commons/data"

def scalar_V(n, comps):
    bad = 0
    for m in range(1 << n):
        v = [(m >> (n - 1 - c)) & 1 for c in range(n)]
        for i, j in comps:
            if v[i] > v[j]: v[i], v[j] = v[j], v[i]
        if any(v[k] > v[k + 1] for k in range(n - 1)): bad += 1
    return bad

def asap_depth(comps):
    lay = {}; mx = 0
    for i, j in comps:
        l = max(lay.get(i, 0), lay.get(j, 0)); lay[i] = lay[j] = l + 1; mx = max(mx, l + 1)
    return mx

def walk(o, n_hint=None, out=None, path=""):
    if out is None: out = []
    if isinstance(o, dict):
        nn = o.get("n", n_hint)
        c = o.get("comparators")
        if isinstance(c, list) and c and all(isinstance(p, (list, tuple)) and len(p) == 2 for p in c):
            out.append((nn, c, o, path))
        for k, v in o.items():
            walk(v, nn, out, path + "/" + str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            walk(v, n_hint, out, path + "[%d]" % i)
    return out

agree = disagree = noclaim = skipped = 0
issues = []
byagent = {}
for f in sorted(glob.glob(os.path.join(ROOT, "*.json"))):
    try:
        d = json.load(open(f))
    except Exception:
        continue
    recs = walk(d)
    if not recs: continue
    owner = os.path.basename(f).split("_")[0]
    for nn, c, rec, path in recs:
        comps = [tuple(p) for p in c]
        if not isinstance(nn, int) or nn < 2 or nn > 13:
            skipped += 1; continue
        if max(max(p) for p in comps) >= nn or min(min(p) for p in comps) < 0:
            skipped += 1; continue
        if (1 << nn) * len(comps) > 3_000_000:
            skipped += 1; continue
        V = scalar_V(nn, comps); D = asap_depth(comps)
        claims = {}
        for key in ("V", "V_upper_bound", "unsorted", "unsorted_inputs"):
            if isinstance(rec.get(key), int): claims["V"] = rec[key]
        for key in ("size",):
            if isinstance(rec.get(key), int): claims["size"] = rec[key]
        for key in ("actual_depth", "depth", "D"):
            if isinstance(rec.get(key), int) and key != "D": claims["depth"] = rec[key]
        ok = True; why = []
        if "V" in claims and claims["V"] != V:
            ok = False; why.append("V claimed %s, recomputed %d" % (claims["V"], V))
        if "size" in claims and claims["size"] != len(comps):
            ok = False; why.append("size claimed %s, actual %d" % (claims["size"], len(comps)))
        if "depth" in claims and claims["depth"] != D:
            ok = False; why.append("depth claimed %s, ASAP %d" % (claims["depth"], D))
        st = byagent.setdefault(owner, [0, 0, 0])
        if not claims:
            noclaim += 1; st[2] += 1
        elif ok:
            agree += 1; st[0] += 1
        else:
            disagree += 1; st[1] += 1
            issues.append((os.path.basename(f)[:52], path[:34], nn, len(comps), V, D, "; ".join(why)))
        if time.time() - t0 > 480: break
    if time.time() - t0 > 480: break

print("VERIFICATION SWEEP of every comparator list in commons/data")
print("  records checked        %4d   (AGREE %d · DISAGREE %d · NO CHECKABLE CLAIM %d)"
      % (agree + disagree + noclaim, agree, disagree, noclaim))
print("  records skipped        %4d   (n out of range, malformed, or too costly)" % skipped)
print()
print("  by agent (agree / disagree / no-claim):")
for a in sorted(byagent):
    print("    %-14s %4d / %4d / %4d" % (a, *byagent[a]))
if issues:
    print()
    print("  DISAGREEMENTS (%d):" % len(issues))
    for f, p, nn, sz, V, D, why in issues[:20]:
        print("    %-52s n=%2d size=%2d recomputed V=%d depth=%d" % (f, nn, sz, V, D))
        print("        %s" % why)
else:
    print()
    print("  NO DISAGREEMENTS. Every checkable claim in commons/data recomputes exactly.")
print("  elapsed %.0fs" % (time.time() - t0))
